use c6_core::{core_stream::ThroughFirstPlayer,core_player::Boundary,map,unit};
use std::io::{Read,Write};
fn main(){let mut input=Vec::new();std::io::stdin().read_to_end(&mut input).unwrap();
let v=ThroughFirstPlayer::decode(&input,map::Limits::default(),unit::Limits::default()).unwrap();
assert_eq!(v.player_prefix.boundary,Boundary::AIMilitary);
assert_eq!(v.tail,&input[v.consumed..]);assert!(std::ptr::eq(v.tail.as_ptr(),input[v.consumed..].as_ptr()));
let(encoded,post_items)=v.player_prefix.encode_prefix_with_items(unit::Limits::default()).unwrap();assert_eq!(encoded,input[v.core.consumed..v.consumed]);assert_eq!(v.items_used,v.core.items_used+post_items);
let p=v.player_prefix.first_player.as_ref().unwrap();assert!(p.header.saved_was_ever_alive());assert_eq!(v.player_prefix.unfinished_player_entries,43);
let arrays=p.post_heroes_arrays.as_ref().unwrap();
let mut parts=vec![p.heroes.encode_with_items(unit::Limits::default()).unwrap()];
for a in [&arrays.unit_definitions,&arrays.feature_definitions,&arrays.continent_definitions]{parts.push((a.encode(unit::Limits::default()).unwrap(),a.pairs.len()));}
parts.push(p.ai_control.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_influence_map.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_planning.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());
assert!(!v.player_prefix.first_player_complete());assert!(p.tail.is_none());parts.push(p.ai_city_manager.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_culture.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());
parts.push(p.ai_diplomatic.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_economic.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_governors.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_grand_strategic.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());parts.push(p.ai_homeland.as_ref().unwrap().encode_with_items(unit::Limits::default()).unwrap());
let mut cursor=v.consumed-parts.iter().map(|x|x.0.len()).sum::<usize>();assert_eq!(cursor,5213659);let mut fields=vec![v.core.consumed,v.consumed,v.items_used,post_items,v.tail.len(),v.core.logical_allocation_used];for (b,i) in &parts{assert_eq!(b,&input[cursor..cursor+b.len()]);fields.extend([cursor,b.len(),*i]);cursor+=b.len();}
let shared=map::Limits{max_bytes:v.consumed,max_items:v.items_used,max_allocation:v.core.logical_allocation_used,..map::Limits::default()};let player=unit::Limits{max_bytes:encoded.len(),max_items:post_items};assert!(ThroughFirstPlayer::decode(&input,shared,player).is_ok());
for s in [map::Limits{max_bytes:shared.max_bytes-1,..shared},map::Limits{max_items:shared.max_items-1,..shared}]{assert!(ThroughFirstPlayer::decode(&input,s,player).is_err());}
for l in [unit::Limits{max_bytes:player.max_bytes-1,..player},unit::Limits{max_items:player.max_items-1,..player}]{assert!(ThroughFirstPlayer::decode(&input,shared,l).is_err());assert!(v.player_prefix.encode_prefix_with_items(l).is_err());}
assert_eq!(v.player_prefix.encode_prefix_with_items(player).unwrap(),(encoded.clone(),post_items));
for cut in fields[6..].chunks_exact(3).map(|x|x[0]).chain(std::iter::once(v.consumed-1)){assert!(ThroughFirstPlayer::decode(&input[..cut],map::Limits::default(),unit::Limits::default()).is_err());}
println!("{}",fields.iter().map(usize::to_string).collect::<Vec<_>>().join(" "));std::io::stdout().write_all(&encoded).unwrap();}
